function formEmail(value) {
  const email = typeof value === "string" ? value.trim().toLowerCase() : "";
  if (
    email.length > 254 ||
    !/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(
      email,
    )
  ) {
    throw new Error("A business email address is required");
  }
  return email;
}

function leadSettings(email, recipient, threshold) {
  if (!Number.isFinite(threshold) || threshold < 0 || threshold > 100) {
    throw Error("Set a numeric minimum fit score between 0 and 100.");
  }
  const businessEmail = formEmail(email);
  let notificationEmail;
  try {
    notificationEmail = formEmail(recipient);
  } catch {
    throw Error("Set one valid internal notification email address.");
  }
  return { email: businessEmail, recipient: notificationEmail, threshold };
}

const settings = {
  recipient: "",
  threshold: 60,
};
return [
  {
    json: leadSettings(
      $input.first().json["What's your business email?"],
      settings.recipient,
      settings.threshold,
    ),
  },
];

function verifyLead(email, data, statusCode = 200) {
  if (statusCode !== 200 || typeof data?.status !== "string") {
    return { valid: false, status: "verification_unavailable", url: "", password: "" };
  }
  if (data.status !== "valid")
    return { valid: false, status: "email_not_valid", url: "", password: "" };
  if (typeof data.email !== "string" || data.email.toLowerCase() !== email) {
    return { valid: false, status: "verification_mismatch", url: "", password: "" };
  }
  return {
    valid: true,
    status: "verified",
    url: "https://api.madkudu.com/v1/persons?email=" + encodeURIComponent(email),
    password: "",
  };
}

const { statusCode, body } = $input.first().json;
return [
  {
    json: verifyLead(
      $("Read the email and set the notification recipient").first().json.email,
      body?.data,
      statusCode ?? 0,
    ),
  },
];

function prepareLeadAlert(scope, person, statusCode) {
  const skip = (status) => ({ status, send: false, recipient: "", subject: "", body: "" });
  if (statusCode === 404) return skip("person_not_found");
  if (statusCode !== 200) return skip("score_unavailable");
  if (
    person?.object_type !== "person" ||
    typeof person.email !== "string" ||
    person.email.toLowerCase() !== scope.email
  ) {
    return skip("score_mismatch");
  }
  const { properties } = person;
  const fit = properties?.customer_fit;
  if (!Number.isFinite(fit?.score) || fit.score < 0 || fit.score > 100)
    return skip("score_unavailable");
  if (fit.score <= scope.threshold) return skip("score_below_threshold");
  const oneLine = (field) =>
    typeof field === "string"
      ? field
          .replace(/[\u0000-\u001f\u007f\s]+/gu, " ")
          .trim()
          .slice(0, 140)
      : "";
  const name =
    [oneLine(properties.first_name), oneLine(properties.last_name)].filter(Boolean).join(" ") ||
    scope.email;
  const company = person.company?.properties;
  const companyName = oneLine(company?.name),
    domain = oneLine(company?.domain);
  const organization =
    companyName && domain ? companyName + " (" + domain + ")" : companyName || domain;
  const location = [oneLine(company?.location?.state), oneLine(company?.location?.country)]
    .filter(Boolean)
    .join(", ");
  const signals = [fit.top_signals_formated, fit.top_signals_formatted].find(
    (item) => typeof item === "string" && item.trim(),
  );
  const summary =
    "Got a hot lead for you: " +
    name +
    (organization ? " from " + organization : "") +
    (location ? ", based in " + location : "") +
    ".";
  return {
    status: "qualified",
    send: true,
    recipient: scope.recipient,
    subject: "⭐ Hot lead alert: " + name,
    body:
      summary +
      (signals
        ? "\n\n" +
          signals
            .replace(/\u0000/g, "")
            .trim()
            .slice(0, 12000)
        : ""),
  };
}

const { statusCode, body } = $input.first().json;
return [
  {
    json: prepareLeadAlert(
      $("Read the email and set the notification recipient").first().json,
      body,
      statusCode,
    ),
  },
];

function leadSendReceipt(id) {
  const confirmed = typeof id === "string" && Boolean(id.trim());
  return { status: confirmed ? "sent" : "email_unconfirmed", messageId: confirmed ? id : null };
}

const result = leadSendReceipt($input.first().json.id);
if (result.status === "email_unconfirmed")
  throw Error("Gmail send unconfirmed. Check Sent before retrying.");
return [{ json: result }];
